const iceHareSheet=new Image();iceHareSheet.assetSrc='assets/ice-hare-v1.png';
function beginIceHare(e){let dx=e.x-p.x,dy=e.y-p.y,d=Math.hypot(dx,dy)||1,origin={x:e.x,y:e.y},target={...origin};for(let r=5;r<=110;r+=5){let q={x:origin.x+dx/d*r,y:origin.y+dy/d*r};if(!passable(q.x,q.y,16)||!lineClear(target,q,16))break;target=q;}e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'iceHareFan',bespoke:true,windup:1.3,origin,target,last:{...origin},blocked:false,locked:false,fired:false,lanes:[]};}
function iceHareReach(origin,angle){let reach=0;for(let r=10;r<=360;r+=10){if(!lineClear(origin,{x:origin.x+Math.cos(angle)*r,y:origin.y+Math.sin(angle)*r}))break;reach=r;}return reach;}
function iceHareLaneContains(a,l,point){let dx=point.x-a.castOrigin.x,dy=point.y-a.castOrigin.y,c=Math.cos(l.angle),s=Math.sin(l.angle),along=dx*c+dy*s,side=-dx*s+dy*c;return along>=35-1e-8&&along<=l.reach+1e-8&&Math.abs(side)<=18+1e-8;}
const iceHareAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r5e1')return iceHareAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='iceHareFan'){
  e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=260&&clear){beginIceHare(e);return;}e.state='idle';if(d>800&&!e.aware||d<=180)return;if(e.nav<=0){e.nav=.6;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,105*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,16)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;
 }
 if(dist(e,a.last)>24){e.attack=null;e.state='idle';e.t=1.5;return;}
 e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.locked&&e.elapsed>=.4){let t=e.elapsed>=.7?1:Math.max(0,(e.elapsed-.4)/.3),q={x:a.origin.x+(a.target.x-a.origin.x)*t,y:a.origin.y+(a.target.y-a.origin.y)*t};if(!a.blocked){let dx=q.x-e.x,dy=q.y-e.y,n=Math.max(1,Math.ceil(Math.hypot(dx,dy)/5));for(let i=0;i<n;i++){let next={x:e.x+dx/n,y:e.y+dy/n};if(!passable(next.x,next.y,16)||!lineClear(e,next,16)){a.blocked=true;break;}e.x=next.x;e.y=next.y;}}a.last={x:e.x,y:e.y};}
 if(!a.locked&&e.elapsed>=.7){a.locked=true;a.castOrigin={x:e.x,y:e.y};let angle=Math.atan2(p.y-e.y,p.x-e.x);a.lanes=[-.48,0,.48].map(offset=>({angle:angle+offset,reach:iceHareReach(a.castOrigin,angle+offset)}));e.facing=Math.cos(angle)-Math.sin(angle)<0?-1:1;}
 if(!a.fired&&e.elapsed>=1.3){a.fired=true;e.struck=true;for(let l of a.lanes)l.reach=Math.min(l.reach,iceHareReach(a.castOrigin,l.angle));if(a.lanes.some(l=>iceHareLaneContains(a,l,p))&&lineClear(a.castOrigin,p))hurt(42);playSound('frost',e.x,e.y);}
 if(e.elapsed>=2){e.attack=null;e.state='idle';e.t=2.6;}
};
const iceHareDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{
 if(e.species!=='r5e1'||!iceHareSheet.complete||!iceHareSheet.naturalWidth||!iceHareSheet.naturalHeight)return iceHareDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='iceHareFan')f={row:2,col:e.elapsed<.4?0:e.elapsed<.7?1:e.elapsed<1.3?2:3};let q=project(e.x,e.y),sw=iceHareSheet.naturalWidth/4,sh=iceHareSheet.naturalHeight/3,w=180,h=w*sh/sw,anchor=[.86,.84,.84][f.row];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,iceHareSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(iceHareSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;
};
const iceHareSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r5e1'?110:iceHareSizeBase(e);
const iceHareGroundBase=drawGroundEffects;drawGroundEffects=()=>{iceHareGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r5e1'):enemies)){let a=e.attack;if(e.species!=='r5e1'||e.hp<=0||a?.pattern!=='iceHareFan'||!a.locked||e.elapsed>=1.55||!visibleAt(e.x,e.y))continue;for(let l of a.lanes){if(l.reach<35)continue;let c=Math.cos(l.angle),s=Math.sin(l.angle),point=(r,side)=>project(a.castOrigin.x+c*r-s*side,a.castOrigin.y+s*r+c*side);ctx.save();ctx.strokeStyle=a.fired?'#e0fbff':'#79d4e7';ctx.fillStyle=a.fired?'#bdefff55':'#5eafc422';ctx.lineWidth=a.fired?3:1;ctx.beginPath();for(let [i,[r,side]]of [[35,-18],[l.reach,-18],[l.reach,18],[35,18]].entries()){let q=point(r,side);if(i)ctx.lineTo(q.x,q.y);else ctx.moveTo(q.x,q.y);}ctx.closePath();ctx.fill();ctx.stroke();if(a.fired){let start=point(35,0),tip=point(l.reach,0);ctx.beginPath();ctx.moveTo(start.x,start.y-16);ctx.lineTo(tip.x,tip.y-16);ctx.stroke();}ctx.restore();}}};
